"""Hold every AGENTS.md to a generated pointer at the CLAUDE.md beside it.

The repo keeps one agent guide per directory, in ``CLAUDE.md``. Claude Code
reads that file; Codex, Cursor and other agents read ``AGENTS.md``. When both
held content they drifted: the root ``AGENTS.md`` lacked the confidentiality
rule and five of the guide's pointers (FND-4273), and the toolkit's described a
layout that no longer existed (FND-4932). So ``AGENTS.md`` is no longer written
by hand. It is the fixed text :func:`render` returns, which sends the agent to
``CLAUDE.md``, and this script fails when it is anything else.

Checked, for every tracked ``CLAUDE.md`` and ``AGENTS.md``:

* each ``CLAUDE.md`` has an ``AGENTS.md`` beside it, so no agent misses it;
* each ``AGENTS.md`` has a ``CLAUDE.md`` beside it to point at;
* each ``AGENTS.md`` is byte-for-byte the rendered pointer.

Usage::

    python .github/scripts/check_agents_md_sync.py          # check
    python .github/scripts/check_agents_md_sync.py --fix    # rewrite AGENTS.md

``--fix`` writes the pointer for every ``CLAUDE.md`` (creating a missing
``AGENTS.md``); it never touches ``CLAUDE.md``. An ``AGENTS.md`` with no
``CLAUDE.md`` is reported but not deleted: whether its content belongs in a new
``CLAUDE.md`` is a human decision. Exits 1 and prints one line per problem.
"""

from __future__ import annotations

import argparse
import subprocess
import sys
from pathlib import Path, PurePosixPath
from typing import Sequence

GUIDE = "CLAUDE.md"
POINTER = "AGENTS.md"
SCRIPT = ".github/scripts/check_agents_md_sync.py"


def render() -> str:
    """Return the text every AGENTS.md must hold."""
    return (
        "# AGENTS.md\n"
        "\n"
        f"The agent guide for this directory is [`{GUIDE}`]({GUIDE}). It applies\n"
        "to every agent, not only Claude Code: read it before changing anything\n"
        "here.\n"
        "\n"
        f"This file is generated by `{SCRIPT}` so the two\n"
        f"cannot drift apart. Do not edit it; edit `{GUIDE}`, and run that script\n"
        "with `--fix` if this text ever changes.\n"
    )


def tracked_guides(root: Path) -> list[PurePosixPath]:
    """Return every tracked CLAUDE.md and AGENTS.md, relative to *root*."""
    out = subprocess.run(
        ["git", "ls-files", "-z", "--", GUIDE, POINTER, f"**/{GUIDE}", f"**/{POINTER}"],
        cwd=root,
        check=True,
        capture_output=True,
        text=True,
    ).stdout
    return sorted(PurePosixPath(p) for p in out.split("\0") if p)


def _within(path: Path, root: Path) -> bool:
    """Return whether *path*, with every symlink resolved, is under *root*."""
    return path.resolve().is_relative_to(root.resolve())


def check(root: Path, paths: Sequence[PurePosixPath], *, fix: bool) -> list[str]:
    """Return one message per problem among *paths*; with *fix*, repair them."""
    present = set(paths)
    dirs = sorted({p.parent for p in paths})
    expected = render()
    problems: list[str] = []
    for d in dirs:
        guide, pointer = d / GUIDE, d / POINTER
        if guide not in present:
            problems.append(
                f"{pointer}: no {GUIDE} beside it; move its content into a new "
                f"{guide} and regenerate {pointer} with --fix"
            )
            continue
        target = root / pointer
        # A tracked symlink could point outside the checkout, and --fix would
        # then overwrite whatever it points at. Refuse it, and anything else
        # that resolves out of root, instead of following it.
        if target.is_symlink() or not _within(target, root):
            problems.append(
                f"{pointer}: is a symlink or resolves outside the repository; "
                "replace it with a regular file (--fix will not write through it)"
            )
            continue
        actual = target.read_text(encoding="utf-8") if target.is_file() else None
        if actual == expected:
            continue
        if fix:
            target.write_text(expected, encoding="utf-8", newline="\n")
            print(f"{pointer}: rewritten")
            continue
        if actual is None:
            problems.append(f"{pointer}: missing; every {GUIDE} needs one")
        else:
            problems.append(
                f"{pointer}: differs from the generated pointer; put content in "
                f"{guide}, not here"
            )
    return problems


def main(argv: Sequence[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Hold every AGENTS.md to a generated pointer at its CLAUDE.md."
    )
    parser.add_argument(
        "--fix", action="store_true", help="rewrite each AGENTS.md to the pointer"
    )
    parser.add_argument(
        "--root", type=Path, default=Path("."), help="repository root (default: .)"
    )
    args = parser.parse_args(argv)
    problems = check(args.root, tracked_guides(args.root), fix=args.fix)
    for problem in problems:
        print(problem)
    if problems:
        print(f"Fix: python {SCRIPT} --fix")
    return 1 if problems else 0


if __name__ == "__main__":
    sys.exit(main())
